	t.Run("valid certificate file", func(t *testing.T) {
		tempDir := t.TempDir()
		certPath := filepath.Join(tempDir, "valid.crt")
		err := os.WriteFile(certPath, []byte(validCert), 0600)
		assert.NoError(t, err)

		derBytes, err := loadCert(certPath)
		assert.NoError(t, err)
		assert.NotEmpty(t, derBytes)
		assert.Equal(t, validDer, derBytes)
	})

	t.Run("file not found", func(t *testing.T) {
		_, err := loadCert("nonexistingfile.crt")
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "no such file or directory")
	})

	t.Run("invalid PEM content", func(t *testing.T) {
		tempDir := t.TempDir()
		certPath := filepath.Join(tempDir, "invalid.crt")
		err := os.WriteFile(certPath, []byte("HELLO WORLD"), 0600)
		assert.NoError(t, err)

		_, err = loadCert(certPath)
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "failed to decode PEM block from certificate file")
	})

	t.Run("invalid certificate data in PEM", func(t *testing.T) {
		tempDir := t.TempDir()
		certPath := filepath.Join(tempDir, "brokencrt.crt")
		brokenCert := `-----BEGIN CERTIFICATE-----
AAAA
-----END CERTIFICATE-----`
		err := os.WriteFile(certPath, []byte(brokenCert), 0600)
		assert.NoError(t, err)

		_, err = loadCert(certPath)
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "failed to parse certificate")
	})
